/**
 * The provider boundary contract.
 *
 *   Demo and live providers may obtain data differently, but everything above
 *   the provider boundary receives the same contract.
 *
 * These tests run equivalent inputs through both providers and assert the
 * results are shaped identically. The API provider is driven by a stubbed
 * `fetch` returning the same fixtures the demo provider reads, so any
 * divergence is the provider's doing rather than the data's.
 *
 * The diff case is checked against `demo-data/expected-diff.json`, which is
 * generated by the REAL backend diff service — a cross-language check, and the
 * one that would have caught the crash that motivated these tests.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import accountsFixture from "@demo-data/accounts.json";
import alertsFixture from "@demo-data/alerts.json";
import currentScan from "@demo-data/current-scan.json";
import expectedDiff from "@demo-data/expected-diff.json";
import previousScan from "@demo-data/previous-scan.json";
import { apiScanProvider } from "./apiScanProvider.js";
import { demoScanProvider } from "./demoScanProvider.js";

/** Structural fingerprint: key names and value *types*, not values. */
function shapeOf(value, depth = 0) {
  if (value === null || depth > 6) return value === null ? "null" : "…";
  if (Array.isArray(value)) return value.length ? [shapeOf(value[0], depth + 1)] : [];
  if (typeof value === "object") {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((k) => [k, shapeOf(value[k], depth + 1)])
    );
  }
  return typeof value;
}

/** Route a stubbed fetch to the fixture the real API would return. */
function stubApi() {
  global.fetch = vi.fn(async (url) => {
    const path = String(url).replace(/^https?:\/\/[^/]+/, "");
    let body;
    if (path.startsWith("/scan?") || path === "/scan") {
      body = { ...currentScan, alerts: alertsFixture.alerts, persisted: false };
    } else if (path.startsWith("/scans/diff")) {
      body = expectedDiff;
    } else if (path.startsWith("/scans/")) {
      body = currentScan;
    } else if (path.startsWith("/scans")) {
      body = {
        scans: [
          {
            scan_id: currentScan.scan_id,
            created_at: currentScan.created_at,
            resource_count: currentScan.resources.length,
            summary: currentScan.summary,
            vs_previous: expectedDiff.summary,
          },
          {
            scan_id: previousScan.scan_id,
            created_at: previousScan.created_at,
            resource_count: previousScan.resources.length,
            summary: previousScan.summary,
            vs_previous: null,
          },
        ],
      };
    } else if (path.startsWith("/accounts")) {
      body = accountsFixture;
    } else {
      throw new Error(`unstubbed path: ${path}`);
    }
    return { ok: true, status: 200, json: async () => body };
  });
}

beforeEach(stubApi);
afterEach(() => vi.restoreAllMocks());

describe("both providers satisfy the same contract", () => {
  it("declares the same method surface", () => {
    const methods = (p) =>
      Object.keys(p)
        .filter((k) => typeof p[k] === "function")
        .sort();
    expect(methods(demoScanProvider)).toEqual(methods(apiScanProvider));
  });

  it("declares the same capability keys", () => {
    expect(Object.keys(demoScanProvider.capabilities).sort()).toEqual(
      Object.keys(apiScanProvider.capabilities).sort()
    );
  });

  it.each([
    ["getScan", (p) => p.getScan(currentScan.scan_id)],
    ["listScans", (p) => p.listScans()],
    ["listAccounts", (p) => p.listAccounts()],
    ["compareScans", (p) => p.compareScans(previousScan.scan_id, currentScan.scan_id)],
  ])("%s returns the same shape from both providers", async (_name, call) => {
    const [demo, api] = await Promise.all([call(demoScanProvider), call(apiScanProvider)]);
    expect(shapeOf(demo)).toEqual(shapeOf(api));
  });

  it("runScan returns the same shape from both providers", async () => {
    // The demo deliberately simulates latency; don't wait it out for real.
    vi.useFakeTimers();
    const demoPromise = demoScanProvider.runScan();
    await vi.runAllTimersAsync();
    const demo = await demoPromise;
    vi.useRealTimers();

    const api = await apiScanProvider.runScan();
    expect(shapeOf(demo)).toEqual(shapeOf(api));
  });
});

describe("demo compareScans reproduces the real backend diff", () => {
  it("matches the backend's counts exactly", async () => {
    const diff = await demoScanProvider.compareScans(previousScan.scan_id, currentScan.scan_id);
    expect(diff.summary).toEqual(expectedDiff.summary);
  });

  it("nests changed entries as {resource, changes} keyed by field", async () => {
    // The exact shape that was wrong before: a flat resource with an array.
    const diff = await demoScanProvider.compareScans(previousScan.scan_id, currentScan.scan_id);
    const entry = diff.changed[0];

    expect(Object.keys(entry).sort()).toEqual(["changes", "resource"]);
    expect(Array.isArray(entry.changes)).toBe(false);
    expect(entry.resource.resource_id).toBeTruthy();

    for (const [field, delta] of Object.entries(entry.changes)) {
      expect(Object.keys(delta).sort()).toEqual(["from", "to"]);
      expect(delta.from).not.toEqual(delta.to);
      expect(["status", "risk_level"]).toContain(field);
    }
  });

  it("identifies the same added, removed, and changed resources", async () => {
    const diff = await demoScanProvider.compareScans(previousScan.scan_id, currentScan.scan_id);
    const ids = (list, pick = (x) => x) => list.map((x) => pick(x).resource_id).sort();

    expect(ids(diff.added)).toEqual(ids(expectedDiff.added));
    expect(ids(diff.removed)).toEqual(ids(expectedDiff.removed));
    expect(ids(diff.changed, (c) => c.resource)).toEqual(
      ids(expectedDiff.changed, (c) => c.resource)
    );
  });
});

describe("the demo cannot reach the network", () => {
  it("makes no fetch calls for any read operation", async () => {
    vi.useFakeTimers();
    const scan = demoScanProvider.runScan();
    await vi.runAllTimersAsync();
    await scan;
    vi.useRealTimers();

    await demoScanProvider.listScans();
    await demoScanProvider.getScan(currentScan.scan_id);
    await demoScanProvider.compareScans(previousScan.scan_id, currentScan.scan_id);
    await demoScanProvider.listAccounts();
    await demoScanProvider.getCleanupActions();

    expect(global.fetch).not.toHaveBeenCalled();
  });

  it("refuses write operations with an explanatory error", async () => {
    await expect(demoScanProvider.executeCleanup({})).rejects.toThrow(/not available in the demo/i);
    await expect(demoScanProvider.createAccount({})).rejects.toThrow(/not available in the demo/i);
  });
});
